/**
 * Calculate the discount for a single line (includes line discount and bulk discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  let discount = 0;
  const total = lineTotal(line);

  if (line.discountPercent && line.discountPercent > 0) {
    discount += roundCents(total * line.discountPercent / 100);
  }

  if (line.qty >= 10) {
    const amountAfterFirstDiscount = total - discount;
    discount += roundCents(amountAfterFirstDiscount * 0.025);
  }

  return discount;
}

