test('invoiceTotals with tier discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { qty: 1, unitPrice: 8500, sku: 'DES-HOUR', name: 'Design', vatRate: 21, discountPercent: 5 },
      { qty: 1, unitPrice: 9500, sku: 'DEV-HOUR', name: 'Dev', vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert(totals.discount > 0);
  assert.equal(totals.discount, Math.round((8500 + 9500) * 0.05));
});

test('lineDiscount with bulk discount for 10+ units', () => {
  const line = { qty: 10, unitPrice: 1000, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  assert(discount > 0);
  const expectedBulkDiscount = Math.round(10000 * 0.025);
  assert.equal(discount, expectedBulkDiscount);
});

test('lineDiscount with bulk discount for 20 units', () => {
  const line = { qty: 20, unitPrice: 1000, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  const expectedBulkDiscount = Math.round(20000 * 0.025);
  assert.equal(discount, expectedBulkDiscount);
});

test('lineDiscount without bulk discount for 9 units', () => {
  const line = { qty: 9, unitPrice: 1000, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  assert.equal(discount, 0);
});

test('lineDiscount applies bulk discount after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  const lineDiscount1 = Math.round(10000 * 0.1);
  const amountAfterFirstDiscount = 10000 - lineDiscount1;
  const bulkDiscount = Math.round(amountAfterFirstDiscount * 0.025);
  const expectedTotal = lineDiscount1 + bulkDiscount;

  assert.equal(discount, expectedTotal);
});

test('lineVAT calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, discountPercent: 10, sku: 'TEST', name: 'Test', vatRate: 21 };
  const vat = lineVAT(line);

  const lineDiscount1 = Math.round(100000 * 0.1);
  const afterFirstDiscount = 100000 - lineDiscount1;
  const bulkDiscount = Math.round(afterFirstDiscount * 0.025);
  const afterAllDiscounts = 100000 - lineDiscount1 - bulkDiscount;
  const expectedVat = Math.round(afterAllDiscounts * 0.21);

  assert.equal(vat, expectedVat);
});

test('invoiceTotals includes bulk discount in total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { qty: 10, unitPrice: 1000, sku: 'SKU1', name: 'Item', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert(totals.discount > 0);
  const expectedBulkDiscount = Math.round(10000 * 0.025);
  assert.equal(totals.discount, expectedBulkDiscount);
});

test('bulk discount does not apply to qty 10 with existing 10% discount', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 10, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  const expectedDiscount = Math.round(9000 * 0.1);
  assert.equal(discount, expectedDiscount);
});

test('invoiceTotals with multiple lines and bulk discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { qty: 10, unitPrice: 1000, sku: 'SKU1', name: 'Item1', vatRate: 21 },
      { qty: 15, unitPrice: 1000, sku: 'SKU2', name: 'Item2', vatRate: 21 },
      { qty: 5, unitPrice: 1000, sku: 'SKU3', name: 'Item3', vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);

  const bulkDiscount1 = Math.round(10000 * 0.025);
  const bulkDiscount2 = Math.round(15000 * 0.025);
  const expectedDiscount = bulkDiscount1 + bulkDiscount2;

  assert.equal(totals.discount, expectedDiscount);
});

test('lineDiscount with both line discount and bulk discount', () => {
  const line = { qty: 20, unitPrice: 1000, discountPercent: 5, sku: 'TEST', name: 'Test', vatRate: 21 };
  const discount = lineDiscount(line);

  const lineDiscount1 = Math.round(20000 * 0.05);
  const afterLineDiscount = 20000 - lineDiscount1;
  const bulkDiscount = Math.round(afterLineDiscount * 0.025);
  const expectedTotal = lineDiscount1 + bulkDiscount;

  assert.equal(discount, expectedTotal);
});

test('bulk discount threshold at exactly 10 units', () => {
  const line9 = { qty: 9, unitPrice: 1000, sku: 'TEST', name: 'Test', vatRate: 21 };
  const line10 = { qty: 10, unitPrice: 1000, sku: 'TEST', name: 'Test', vatRate: 21 };

  const discount9 = lineDiscount(line9);
  const discount10 = lineDiscount(line10);

  assert.equal(discount9, 0);
  assert(discount10 > 0);
});

