test('invoiceTotals handles different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  const totals = invoiceTotals(r.value);
  const subtotal = 8500 + 100 * 37 + 60000;
  assert.equal(subtotal, 72200);
  assert.equal(totals.subtotal, 72200);
  const discount1 = Math.round(8500 * 0.05);
  const discount2Line = Math.round(3700 * 0.05);
  const discount2Bulk = Math.round((3700 - discount2Line) * 0.025);
  const discount3 = Math.round(60000 * 0.05);
  const expectedDiscount = discount1 + discount2Line + discount2Bulk + discount3;
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, 2040);
  assert.equal(totals.total, 70640);
});

